  let dead=false,paused=false,beginning=false,started=false,elapsed=0,last=0,raf=0,jobs=[],tick=()=>{},input=()=>{},keyUp=()=>{},onPause=()=>{},finished=false,rhythmMusic=null;
  const events=new AbortController();
